import{_ as e,o as l,c as a,a2 as i}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"Palleria の概要","description":"Palleria の概要、特徴、および動作要件","frontmatter":{"title":"Palleria の概要","description":"Palleria の概要、特徴、および動作要件"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786166106000}'),r={name:"guide/index.md"};function n(s,t,o,d,g,c){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="palleria-の概要" tabindex="-1">Palleria の概要 <a class="header-anchor" href="#palleria-の概要" aria-label="Permalink to &quot;Palleria の概要&quot;">​</a></h1><p><strong>Palleria</strong> は Android 13（API レベル 33）以上を対象とした非公式のオープンソース Pixiv クライアントアプリです。 UI フレームワークに <strong>Jetpack Compose</strong> と <strong>Miuix KMP</strong>、通信・データ解読コアに <strong>Rust (UniFFI)</strong> を採用しています。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Palleria は非公式クライアントであり、ピクシブ株式会社とは一切関係ありません。</p></div><hr><h2 id="主な機能仕様" tabindex="-1">主な機能仕様 <a class="header-anchor" href="#主な機能仕様" aria-label="Permalink to &quot;主な機能仕様&quot;">​</a></h2><ul><li><strong>作品閲覧</strong>: イラスト、マンガ（見開き/単ページ）、小説（縦書き/横書き/挿絵表示）、うごイラ（Zip フレーム解凍・再生）、ショートフィード。</li><li><strong>検索システム</strong>: タグ部分一致/完全一致、タイトル・キャプション検索、ユーザー検索、ブックマーク数フィルター、ウォッチリスト（お気に入りタグ）。</li><li><strong>ダウンロード管理</strong>: 原寸保存、一括ダウンロード、並列数設定（1〜5）、作者別/作品別フォルダ振り分け、自動ブックマーク連携。</li><li><strong>セキュリティ・プライバシー</strong>: PIN / 生体認証、電卓偽装モード（計算機能付き偽装画面）、<code>FLAG_SECURE</code> によるスクショ防止、バックグラウンド自動ロック。</li><li><strong>カスタマイズ &amp; 設定</strong>: ライト/ダーク/AMOLED テーマ、動的カラー、プロキシ接続、ユーザー/タグ/作品IDのミュート、JSON 形式の設定バックアップ/復元。</li><li><strong>システム統合</strong>: 定期切り替えライブ壁紙サービス (<code>PalleriaLiveWallpaperService</code>)、ホーム画面ランキング/イラストウィジェット。</li></ul><hr><h2 id="動作要件" tabindex="-1">動作要件 <a class="header-anchor" href="#動作要件" aria-label="Permalink to &quot;動作要件&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">条件 / 仕様</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>最小 OS バージョン</strong></td><td style="text-align:left;">Android 13 (API Level 33) 以上</td></tr><tr><td style="text-align:left;"><strong>ターゲット SDK</strong></td><td style="text-align:left;">Android 14 (API Level 34)</td></tr><tr><td style="text-align:left;"><strong>アーキテクチャ</strong></td><td style="text-align:left;"><code>arm64-v8a</code>, <code>armeabi-v7a</code>, <code>x86_64</code></td></tr><tr><td style="text-align:left;"><strong>開発言語</strong></td><td style="text-align:left;">Kotlin 2.x, Rust (2021 edition)</td></tr><tr><td style="text-align:left;"><strong>ライセンス</strong></td><td style="text-align:left;">GNU General Public License v3.0 (GPL-3.0-only)</td></tr></tbody></table><hr><h2 id="スクリーンショット" tabindex="-1">スクリーンショット <a class="header-anchor" href="#スクリーンショット" aria-label="Permalink to &quot;スクリーンショット&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">ホーム画面</th><th style="text-align:center;">検索画面</th><th style="text-align:center;">ランキング</th><th style="text-align:center;">ユーザープロフィール</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/1.png" width="160" alt="Home"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/2.png" width="160" alt="Search"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/3.png" width="160" alt="Ranking"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/5.png" width="160" alt="Profile"></td></tr></tbody></table>',12)])])}const f=e(r,[["render",n]]);export{p as __pageData,f as default};
